window.VD=window.VD||{};window.VD["vw/touareg-7l"]={"touareg-7l-activate-daytime-running-lights-drl-on-odb":"<p><strong>Purpose</strong>: activates / deactivates the daytime running lights (DRL) on the ODB (on-board computer).  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on ” <strong>Select”</strong>, then click on ” <strong>Select</strong> ” and run the VCDS program.<strong><strong>09 – Cent. Elect.</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then <strong>“<strong>Long Coding Helper</strong>”.</strong></p>\n<p><strong>5</strong> – Select Byte<strong> 0 </strong>:</p>\n<p>Bit<strong> 0 </strong>: Uncheck<em> <strong>“Daytime Running Lights</strong> </em> </p>","touareg-7l-activate-hidden-menu-rns-510":"<p><strong>Purpose</strong>: Activates the hidden menu in RNS 510.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on ” <strong>Select”</strong>, then click on ” <strong>Select</strong> ” and run the VCDS program.<strong><strong>56 – Radio</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>5</strong> – Choose <em><strong>Channel 50</strong> </em>then set the value to <strong>1</strong></p>\n<p><em>Restart the RNS 510.</em></p>\n<p><em>To launch the Hidden Menu, press SETUP (for 6s)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/1T0-035-680-C_Module37_Adaptation_Channel50-1a7d6a90.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/rns510-1024x821-d0438887.webp\"/></figure>","touareg-7l-activate-rns-510-voice-command":"<p><strong>Purpose</strong>: to activate voice control on the RNS 510 (SDS).  </p>\n<p><strong>ATTENTION:</strong> RNS 510 firmware must be version v2660.</p>\n<p>Activating voice control brings up the “Voice control” menu in the RNS 510’s SETUP menu.</p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select”</strong>, then click on “<strong>Select</strong>”, then click on “<strong>Select</strong>”. <strong>Procedure:</strong> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket. <strong><strong>“37 – Navigation</strong></strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p>Byte <strong>3</strong>, check the box for<strong>“Bit 1: Microphone Diagnostics active</strong>”.</p>\n<p>Byte <strong>7</strong>, uncheck the box for<strong>“Bit 1: Voice Control inactive</strong>”.<br/></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/RNS510_Menu_Commande_Vocale-bf5955d7.webp\"/></figure>\n<p>To install the microphone, connect the microphone lead to the rear of the RNS 510. Connect to pins (Mic-)C1 and (Mic+)C7. </p>","touareg-7l-adjusting-light-sensor-sensitivity":"<p><strong>Purpose: </strong>Adjusts the sensitivity of the light sensor.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “2 EPIRBs” module from the drop-down list and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>2</strong>: </em><br/> Bits<em><strong> 0-7</strong></em> (187, 205 or 237 to increase sensitivity, or 45, 40 or 33 to decrease sensitivity)</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/lightsensorg5-1e88d9a5.webp\"/></figure>","touareg-7l-automatic-door-locks":"<p><strong>Purpose: </strong>to set automatic door locking from 15 km/h.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“46 – Comfort module</strong>“.</p>\n<p><strong>4</strong> – Click “<strong>Adaptation 10</strong>.”</p>\n<p><strong>5 –</strong> Channel<strong> 02</strong> (drop-down list (Auto-Lock)) <em>Set value to <strong>1</strong></em></p>","touareg-7l-automatic-door-unlocking":"<p><strong>Purpose: </strong>to set automatic door unlocking when the key is removed.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“46 – Comfort module</strong>“.</p>\n<p><strong>4</strong> – Click “<strong>Adaptation 10</strong>.”</p>\n<p><strong>5 –</strong> Channel<strong> 03</strong> (drop-down list (Auto-Unlock)) <em>Set value to <strong>1</strong></em></p>","touareg-7l-change-odb-language":"<p><strong>Purpose </strong>: To change the language of the ODB.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>17 – Instruments</strong>”.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 04</strong></p>\n<p><em>Set the value according to the selected language</em></p>\n<p><em>1 = German</em><br/><em>2 = English</em><br/><em>3 = French</em><br/><em>4 = Italian</em><br/><em>5 = Spanish</em><br/><em>6 = Portuguese</em></p>","touareg-7l-change-the-rcd-rns-510-theme":"<p><strong>Purpose:</strong> to change the display theme of the RCD 510 and RNS 510.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1</strong>:</p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>” then click on<strong>“37 – Navigation</strong>” for RNS510 and “<strong>56 – Radio</strong>” for RCD510.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>” then “<strong>Long Coding Helper</strong>”.</p>\n<p><strong>5</strong> – Select Byte<strong> 7</strong></p>\n<p><em>Bit <strong>4-5</strong>: Select from 3 themes</em><br/><em>“00 Display Variant: Highline</em><br/><em>“10 Display Variant: Sportsline</em><br/><em>“20 Display Variant: Premium</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/2B758E5F-ACB4-418C-BBBB-B61B0F3A298B-186113f1.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/69C76009-6EC7-465A-A676-8E39BA840A6B-6689b9e0.webp\"/><figcaption>Highline</figcaption></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/3A58F148-9FBB-4DD8-BF05-E03A5351E3A8-e9b6cb9b.webp\"/><figcaption>Sportsline</figcaption></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/4894A3B7-2ED2-4A75-9D46-CA3BFCF5A76C-8fb8de15.webp\"/><figcaption>Premium</figcaption></figure>\n<p>Exit the module and save your changes. The RCD / RNS 510 must now be restarted for the changes to take effect. Press both arrows and the star for 6s.  </p>","touareg-7l-comfort-turn-signal":"<p><strong>Purpose:</strong> to activate and set the number of flashes for the “Comfort flashing” option.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4 </strong>– Click on<strong>“Coding – 07</strong>”.</p>\n<p><strong>5 </strong>– Select <em>Byte <strong>4</strong>: <br/>Bit <strong>3</strong>: Check the “Comfort/Tip Blinking” box</em></p>\n<p><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>09 – Cent. Elect.</strong>“<br/><br/><strong>4 – </strong> Click “<strong>Adaptation – 10</strong>.”</p>\n<p><strong>5 </strong>– In the drop-down list, select Channel <strong>01</strong><strong>“Comfort Turn Signals (Cycles)”.</strong></p>\n<p>Choose a value between 1 and 5 for the number of flashes</p>","touareg-7l-deactivate-brake-pad-warning-light":"<p><strong>Purpose: </strong> Allows you to disable the brake pad wear warning light on the OBD (On-Board Diagnostics) system, for example, for brake pads without a sensor or if the sensor is malfunctioning / Brake Pad Warning Light Deactivation. </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>17 – Instruments.”</strong><br/><br/><strong>4 </strong>– Click on “<strong>Coding – 07</strong>”.  </p>\n<p>The third<em>  and fourth coding digits (xx<strong>??</strong>x0x) are used to modify Instrument module options. To suppress <em><em>the brake pad indicator</em></em>subtract <strong>1</strong> from these digits. </em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/7L6-920-875-G_Module17_Coding-8efa5107.webp\"/></figure>\n<p>For example, if the initial coding (with the wafer indicator) is:<strong>0007101</strong></p>\n<p>To delete the indicator plate, simply recode as follows:<strong>0006101</strong><em>(07 – 01 = 06)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/voyant-frein-d4619ec9.gif\"/></figure>","touareg-7l-deactivate-windshield-washer-indicator":"<p><strong>Purpose </strong>: to deactivate the windshield washer indicator on the ODB (on-board computer).  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>17 – Instruments</strong>”.<br/><br/><strong>4 </strong>– Click on “<strong>Coding – 07</strong>”.  </p>\n<p>The third<em>  and fourth coding digits (xx<strong>??</strong>x0x) are used to modify Instrument module options. To suppress <em><em>washer indicator</em></em>subtract <strong>4</strong> from these digits. </em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/7L6-920-875-G_Module17_Coding-8efa5107.webp\"/></figure>\n<p>For example, if the initial coding (<em><em>with windshield washer indicator</em></em>) is:<strong>0007101</strong></p>\n<p>To delete the windscreen washer indicator, simply recode as follows:<strong>0003101</strong>(07 – 04 = 03)</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/laveglace-edc83d4f.webp\"/></figure>","touareg-7l-delete-belt-alarm":"<p><strong>Purpose </strong>: To suppress the audible alarm and the warning light on the speedometer when driving without a seatbelt.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>17 – Instruments</strong>”.<br/><br/><strong>4 </strong>– Click on “<strong>Coding – 07</strong>”.  </p>\n<p>The third<em>  and fourth coding digits (xx<strong>??</strong>x0x) are used to modify Instrument module options. To suppress the belt alarm, subtract <strong>2</strong> from these digits. </em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/7L6-920-875-G_Module17_Coding-8efa5107.webp\"/></figure>\n<p>For example, if the initial coding (with belt alarm) is:<strong>0007101</strong></p>\n<p>To delete the belt alarm, simply recode as follows:<strong>0005101</strong><em>(07 – 02 = 05)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/voyant_ceinture_de_securite-296648a9.webp\"/></figure>","touareg-7l-flash-mode-lights-during-emergency-braking":"<p><strong>Purpose</strong>: activates the brake/turn signal lights in flash mode during emergency braking.  </p>\n<p><strong>Procedure </strong>: <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“46- Central Conv.</strong></p>\n<p>4 – Click on “Coding – 07” then “Long Coding Helper”.</p>\n<p><strong>5</strong> – <em>Select Byte <strong>4</strong>: </em><br/><em>Bit <strong>4</strong>: Check “Emergency Brake Blinking”.</em></p>","touareg-7l-lock-cd-dvd-eject-button-on-rns-510":"<p><strong>Purpose</strong>: locks/unlocks the RNS 510’s CD/DVD eject button.  </p>\n<p><em>Protection against theft of your navigation DVD.  </em></p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on ” <strong>Select”</strong>, then click on ” <strong>Select</strong> ” and run the VCDS program. <strong><strong>37 – Navigation</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>5</strong> – Select <em><strong>Channel 43</strong> (Ejection Lock)</em> then set the value to <strong>1</strong> <em>(CD/DVD Ejection Lock active)</em></p>\n<p><em>Restart the RNS 510.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/rns510-1024x821-d0438887.webp\"/></figure>","touareg-7l-ops-speed-camera-display-on-car-radio-screen":"<p><strong>Purpose:</strong> Enables the display of OPS speed cameras on the car radio screen.  </p>\n<p><strong><em>Please note: The vehicle must be equipped with a compatible car radio (RCD-310, RCD-510, RNS-315, RNS-510).</em></strong> </p>\n<p><strong>Procedure </strong>: <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“10-Station assistance</strong>”.</p>\n<p><strong>4</strong> – Click “<strong>Security Access – 16</strong>,” then enter the code “<strong>71679</strong>“</p>\n<p><strong>5</strong> – Click on<strong>“Coding- 07</strong>”. then click on<strong>“Long Coding Helper</strong>”.</p>\n<p><strong>6 – </strong>Select <em>Byte<strong> 0</strong>: </em><br/><em>Bit <strong>4</strong>: Tick “Optical illustration active”.</em></p>","touareg-7l-pilot-suspension-calibration":"<p><strong>Purpose:</strong> to recalibrate the pilot-controlled suspension reference height to the original values.  </p>\n<p><strong>Original suspension height</strong> </p>\n<p>VW Touareg (7L): 497 mm (front) and 502 mm (rear) <br/>VW Touareg (7L) Offroad: 488 mm (front) and 498 mm (rear)  </p>\n<p><strong>Prerequisites</strong> </p>\n<p>The gear selector must be in neutral (manual gearbox) / in position “P” (automatic gearbox)<br/>Start the engine, it must run throughout the calibration, do not switch off the ignition<br/>All doors must be closed, and not opened during calibration.</p>\n<h3><strong>Measurement of actual suspension height</strong></h3>\n<p>It is necessary to measure and record the actual height of each suspension.<br/>The suspension height is the vertical distance between the middle of the wheel and the lower edge of the fender at the wheel arch.</p>\n<p><br/><br/><br/><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on<strong>“Select”</strong>, then click on<strong> “34 – Correct trim”</strong>. 2 – Switch on the ignition and run the VCDS program. <strong>Procedure:</strong> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31564</strong>”<br/><br/> 4 – Click on<strong>“Adaptation – 10</strong>”<br/><br/> 5 –<strong> Channel 01</strong>: <em>Left front suspension adjustment </em><br/><em>Enter the previously measured value</em></p>\n<p><strong>Channel 02 </strong>: <em>Front right suspension adjustment </em><br/><em>Enter previously measured value</em></p>\n<p><strong>Channel 03</strong>: <em>Left rear suspension adjustment </em><br/><em>Enter previously measured value</em></p>\n<p><strong>Channel 04</strong>: <em>Right rear suspension adjustment </em><br/><em>Enter previously measured value</em></p>\n<p><strong>Channel 05 </strong>: <em>Set value <strong>1</strong></em></p>","touareg-7l-radar-deactivation-speed":"<p><strong>Purpose: </strong>Allows you to select the speed at which speed cameras are deactivated.  </p>\n<p><strong>Procedure:</strong> <br/><strong>1</strong> – With the engine off and the ignition switched off, connect your official VAG-COM VCDS cable to the computer, then connect the other end to your vehicle’s diagnostic port.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“76 – Stationnt help</strong>”.</p>\n<p><strong>4</strong> – Click “<strong>Adaptation 10</strong>.”</p>\n<p><strong>5 </strong>– Channel <strong>03</strong> ( Choose the new speed, between 1 and 15 km/h )</p>","touareg-7l-radar-volume":"<p><strong>Purpose: </strong>To set parking radar volumes.  </p>\n<p><strong>Procedure:</strong> <br/><strong>1</strong> – With the engine off and the ignition switched off, connect your official VAG-COM VCDS cable to the computer, then connect the other end to your vehicle’s diagnostic port.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1 (Radar Front) :</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“76 – Stationnt help</strong>”.</p>\n<p><strong>4</strong> – Click “<strong>Adaptation 10</strong>.”</p>\n<p><strong>5 </strong>– Channel <strong>01</strong> ( Choose the new value according to the desired volume, between 0 and 100% )</p>\n<p><strong>Line 2 (Rear Radar):</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“76 – Stationnt help</strong>”.</p>\n<p><strong>4</strong> – Click “<strong>Adaptation 10</strong>.”</p>\n<p><strong>5 </strong>– Channel <strong>02</strong> ( Choose the new value according to the desired volume, between 0 and 100% )</p>","touareg-7l-selective-door-unlocking":"<p><strong>Purpose: Allows </strong>you to configure selective door unlocking. </p>\n<p>When unlocking the vehicle, only the driver’s door and the rear door on the driver’s side (depending on the programming) will be unlocked. To unlock all doors, press the unlock button on the remote control twice.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“46 – Comfort module</strong>“.</p>\n<p><strong>4</strong> – Click “<strong>Adaptation 10</strong>.”</p>\n<p><strong>5 –</strong> Channel<strong> 01</strong>:</p>\n<p><em>Set the value to 1 to unlock only the driver’s door</em><br/><em>Set the value to 2 to unlock only the front and rear doors on the driver’s side</em></p>","touareg-7l-speed-limit-display-rns-510":"<p><strong>Purpose </strong>: to display the speed limit on the RNS 510 navigation screen.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1</strong>:</p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>” then click on<strong>“37 – Navigation</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”. Then “<strong>Long Coding Helper</strong>”.</p>\n<p><strong>5</strong> – Select Byte<strong> 7</strong><br/>Activate Bit <strong>2</strong>: Speed Threshold for Destination Input active</p>\n<p>+ use voice command to activate Bit 3: Speed Threshold for Speech Destination Input active</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/2B758E5F-ACB4-418C-BBBB-B61B0F3A298B-186113f1.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/rns510speed-9dcbaa67.webp\"/></figure>"};
